def ask_validated(text, tries=3):
    msgs = [{"role":"user","content":PROMPT.format(text=text)}]
    for attempt in range(tries):
        out = client.chat.completions.create(
            model="meta/llama-3.1-8b-instruct",
            temperature=0, messages=msgs
        ).choices[0].message.content
        try:
            data = json.loads(out)
            assert data["decision"] in ("approved","rejected","unclear")
            return data, attempt + 1
        except Exception as e:
            msgs += [{"role":"assistant","content":out},
                     {"role":"user","content":f"That was invalid: {e}. Return only valid JSON."}]
    raise ValueError("no valid output after retries")

