import json

def agent(question, max_steps=5, verbose=True):
    msgs = [{"role":"system","content":
             "Use the tools when a fact is needed. Never guess a number."},
            {"role":"user","content":question}]
    for step in range(max_steps):
        r = client.chat.completions.create(
            model="meta/llama-3.1-8b-instruct",
            temperature=0, messages=msgs, tools=tools
        ).choices[0].message

        if not getattr(r, "tool_calls", None):
            if verbose: print(f"[step {step}] final answer")
            return r.content

        msgs.append(r)
        for call in r.tool_calls:
            args = json.loads(call.function.arguments)
            result = run_tool(call.function.name, args)
            if verbose:
                print(f"[step {step}] {call.function.name}({args}) -> {result}")
            msgs.append({"role":"tool","tool_call_id":call.id,
                         "content":json.dumps(result)})
    return "STOPPED: step budget exhausted"

