def programmatic_checks(record, retrieved_ids):
    issues = []
    if record["found"] and not record.get("source_chunk_ids"):
        issues.append("claimed found but cited nothing")
    for cid in record.get("source_chunk_ids", []):
        if cid not in retrieved_ids:
            issues.append(f"cited chunk {cid} that was never retrieved")
    q = record.get("supporting_quote", "")
    if q and not any(q[:40] in chunks[i] for i in retrieved_ids):
        issues.append("quote not found verbatim in any retrieved chunk")
    return issues

